import{_ as n,c as t,o as i,ax as o}from"./chunks/framework.DHqKNX4U.js";const g=JSON.parse('{"title":"Single Sign-On (SSO)","description":"","frontmatter":{},"headers":[],"relativePath":"enterprise/sso/guide.md","filePath":"enterprise/sso/guide.md"}'),a={name:"enterprise/sso/guide.md"};function s(r,e,l,c,d,h){return i(),t("div",null,e[0]||(e[0]=[o('<h1 id="single-sign-on-sso" tabindex="-1">Single Sign-On (SSO) <a class="header-anchor" href="#single-sign-on-sso" aria-label="Permalink to &quot;Single Sign-On (SSO)&quot;">​</a></h1><p>Single Sign-On lets people sign in to Open Archiver with your organisation&#39;s identity provider instead of a local password. Both <strong>OpenID Connect (OIDC)</strong> and <strong>SAML 2.0</strong> are supported, covering providers such as Okta, Microsoft Entra ID, Google Workspace, Keycloak, Authentik, Authelia, and ADFS.</p><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>An administrator configures a connection to the identity provider under <strong>Admin → Single Sign-On</strong>. Once the connection is enabled, a &quot;Continue with …&quot; button appears on the sign-in page. Accounts can be created automatically on first sign-in (just-in-time provisioning), linked to existing accounts by email address, and assigned roles based on the person&#39;s directory groups.</p><p>Signing in through SSO produces exactly the same session as a password login. Multi-factor authentication for SSO users is the identity provider&#39;s responsibility; local TOTP continues to apply to password logins.</p><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><ul><li>Open Archiver Enterprise license with the <strong>SSO</strong> feature enabled.</li><li><code>APP_URL</code> set to the address users reach the application on — every URL exchanged with the identity provider derives from it.</li><li><code>ENCRYPTION_KEY</code> set — the OIDC client secret is stored encrypted with it.</li><li>An application registered at your identity provider (see below).</li></ul><h2 id="examples" tabindex="-1">Examples <a class="header-anchor" href="#examples" aria-label="Permalink to &quot;Examples&quot;">​</a></h2><p>Step-by-step configuration for common identity providers is in <a href="./examples/">SSO Examples</a>:</p><ul><li><a href="./examples/google-workspace.html">Google Workspace</a></li><li><a href="./examples/google-workspace-okta.html">Google Workspace via Okta</a></li><li><a href="./examples/microsoft-365.html">Microsoft 365 (Entra ID)</a></li><li><a href="./examples/microsoft-365-okta.html">Microsoft 365 via Okta</a></li></ul><p>The two sections below describe the generic shape of each protocol; the examples give the exact console steps for a specific provider.</p><h2 id="setting-up-openid-connect" tabindex="-1">Setting up OpenID Connect <a class="header-anchor" href="#setting-up-openid-connect" aria-label="Permalink to &quot;Setting up OpenID Connect&quot;">​</a></h2><ol><li>In your identity provider, create a <strong>web application</strong> using the authorization code flow.</li><li>Register the redirect URI shown on the Open Archiver SSO admin page: <code>{APP_URL}/signin/sso/callback</code>.</li><li>In Open Archiver, choose the <strong>OpenID Connect</strong> protocol and enter the provider&#39;s <strong>issuer URL</strong> (for Keycloak, <code>https://id.example.com/realms/&lt;realm&gt;</code>), the <strong>client ID</strong> and the <strong>client secret</strong>. The remaining endpoints are discovered automatically.</li><li>Add at least one <strong>allowed email domain</strong>. Sign-ins from other domains are refused, for new and existing accounts alike.</li><li>Use <strong>Test connection</strong> to confirm the issuer is reachable, then enable the connection.</li></ol><p>PKCE is always used, and ID tokens are validated against the provider&#39;s published signing keys.</p><h2 id="setting-up-saml-2-0" tabindex="-1">Setting up SAML 2.0 <a class="header-anchor" href="#setting-up-saml-2-0" aria-label="Permalink to &quot;Setting up SAML 2.0&quot;">​</a></h2><ol><li>In Open Archiver, choose the <strong>SAML 2.0</strong> protocol and enter the identity provider&#39;s <strong>metadata URL</strong> (for Keycloak, <code>https://id.example.com/realms/&lt;realm&gt;/protocol/saml/descriptor</code>). If the URL cannot be reached from the server, paste the metadata XML instead.</li><li>In your identity provider, import the Open Archiver <strong>service provider metadata URL</strong> shown on the admin page — it doubles as the SP entity ID — or configure the <strong>ACS URL</strong> (<code>{APP_URL}/signin/sso/callback/saml</code>) manually.</li><li>Configure the provider to release an email address (as the NameID or an email attribute) and, optionally, a group attribute.</li><li>Test and enable the connection as with OIDC.</li></ol><p>Responses from the identity provider are always signature-checked against the certificate in its metadata. Sign-in requests are sent unsigned. IdP-initiated sign-in is not supported: every login starts at the Open Archiver sign-in page.</p><h2 id="accounts-and-roles" tabindex="-1">Accounts and roles <a class="header-anchor" href="#accounts-and-roles" aria-label="Permalink to &quot;Accounts and roles&quot;">​</a></h2><ul><li><strong>Just-in-time provisioning</strong> creates an account the first time a person signs in. The account has no password — it authenticates only through the identity provider.</li><li><strong>Linking</strong> attaches SSO to an existing account with the same email address. It can be turned off, in which case only pre-linked or provisioned accounts may sign in.</li><li><strong>Group mappings</strong> translate the provider&#39;s group values (from the configurable groups claim or attribute) into Open Archiver roles. With <strong>Update roles on every sign-in</strong> enabled, moving a person between directory groups changes their role at their next sign-in. Roles only change when a mapping actually matches — a sign-in that matches nothing leaves the account&#39;s existing roles untouched, so linking or signing in can never demote an existing user (an administrator included) to the default.</li><li>The <strong>default role</strong> applies only when a brand-new account is created and no mapping matched; without one, an unmatched new user is refused.</li></ul><h2 id="multiple-identity-providers" tabindex="-1">Multiple identity providers <a class="header-anchor" href="#multiple-identity-providers" aria-label="Permalink to &quot;Multiple identity providers&quot;">​</a></h2><p>An instance can run several connections at once. Each enabled connection becomes its own button on the sign-in page, so staff on one provider and a partner organisation on another can both sign in, and a migration from one provider to another can run with both live.</p><p>Accounts are bound to the specific connection they signed in through, so two providers never resolve to the same account even when they issue the same subject or use email-format identifiers.</p><h2 id="requiring-sso" tabindex="-1">Requiring SSO <a class="header-anchor" href="#requiring-sso" aria-label="Permalink to &quot;Requiring SSO&quot;">​</a></h2><p>The <strong>Require single sign-on</strong> switch turns off password sign-in for ordinary users. Several safeguards apply:</p><ul><li>The switch stays unavailable until at least one sign-in has completed through the connection, so a configuration that has never worked cannot be enforced. Editing the connection&#39;s identity — its issuer, protocol, client ID or pasted metadata — clears that proof and switches enforcement off until a sign-in succeeds against the new configuration.</li><li><strong>Super Admins always keep password sign-in.</strong> This is the recovery path when the identity provider is down or misconfigured.</li><li>Enforcement is <strong>per connection</strong>, not instance-wide, and only reaches users that connection could actually serve: a user whose email domain is outside every enforcing connection&#39;s allowed domains keeps password sign-in, since SSO would refuse them too and denying the password would close both doors. With several connections configured, you can require SSO for one and leave the other optional.</li></ul><p>If the license lapses, SSO endpoints are disabled and password sign-in returns for everyone — nobody is locked out.</p><h2 id="auditing" tabindex="-1">Auditing <a class="header-anchor" href="#auditing" aria-label="Permalink to &quot;Auditing&quot;">​</a></h2><p>Every SSO sign-in (successful or failed), every just-in-time provisioning, and every configuration change is recorded in the audit log (<code>SSO_LOGIN</code>, <code>SSO_JIT_PROVISION</code>, <code>SSO_CONFIG_UPDATED</code>).</p>',28)]))}const u=n(a,[["render",s]]);export{g as __pageData,u as default};
